var TRT_QUESTIONS = [{"mp": "204.08", "topic": "Confined Space Rescue", "q": "Per MP 204.08, which of the following best defines a confined space?", "opts": ["A space large enough to enter, not designed for continuous occupancy, with limited entry and egress", "Any below-grade room with a single doorway", "Any space where SCBA is required by policy", "A space smaller than 100 square feet with no windows"], "answer": 0, "why": "MP 204.08 defines a confined space by three traits: large enough for personnel to physically enter, not designed for continuous employee occupancy, and limited entry and egress.", "cite": "MP 204.08, Tactical Considerations"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "Which OSHA standard does MP 204.08 name as the basis for confined space rescue operations?", "opts": ["29 CFR 1926 Subpart P", "29 CFR 1910.134 Respiratory Protection", "29 CFR 1910.146 Permit-Required Confined Spaces", "29 CFR 1926.650 Excavations"], "answer": 2, "why": "MP 204.08 states OSHA Standard 29 CFR 1910.146, Permit-Required Confined Spaces, regulates entry and is the basis for confined space rescue operations.", "cite": "MP 204.08, Tactical Considerations"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "At a confined space incident, what is the first arriving company officer required to do?", "opts": ["Begin entry with the first crew while awaiting TRT", "Assume Command, begin an immediate size-up, isolate the hazard area, and deny entry to non-rescue personnel", "Establish Lobby and begin ventilation before sizing up", "Request OSHA response before taking any action"], "answer": 1, "why": "Phase I requires the first arriving company officer to assume Command, size up immediately, isolate the hazard area, and deny entry to all non-rescue personnel.", "cite": "MP 204.08, Phase I — Arrival"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "Per MP 204.08, which unit should be assigned Rescue Sector at a confined space incident?", "opts": ["The first arriving ALS company", "The first arriving ladder company", "Any company the Safety Officer selects", "The first arriving TRT unit staffed with a TRT Company Officer"], "answer": 3, "why": "The first arriving TRT unit staffed with a TRT Company Officer should be assigned Rescue Sector, and that officer should remain with the crew.", "cite": "MP 204.08, Phase I — Arrival"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "When must a Safety Officer be established at a confined space rescue?", "opts": ["Only after the victim is located", "Prior to implementing any rescue plan proposed by Rescue Sector", "Only if the incident extends past one hour", "After the Technical Advisor arrives"], "answer": 1, "why": "A Safety Officer must be established before any rescue plan proposed by Rescue Sector is implemented, per Phase I of MP 204.08.", "cite": "MP 204.08, Phase I — Arrival"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "Before entry at a confined space rescue, what must Rescue Sector ensure is in place and briefed?", "opts": ["Only the entry team, briefed on the rescue plan", "A HazMat team and a PIO, briefed on media staging", "An entry team and a back-up team, briefed on hazards, space configuration, rescue and back-up plans, emergency procedures, and time limits", "Two entry teams, briefed only on the back-up plan"], "answer": 2, "why": "Phase III requires both an entry team and a back-up team in place, briefed on anticipated hazards, the space configuration, the rescue and back-up plans, emergency procedures, and time limits.", "cite": "MP 204.08, Phase III — Entry Operations"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "Per MP 204.08, how is it decided whether a confined space incident is a rescue or a recovery operation?", "opts": ["By the survivability profile: victim location and condition, and elapsed time since the accident", "By the victim's age and the time of day", "By the size of the space and the number of entry points", "By whether an entry permit was issued"], "answer": 0, "why": "Pre-entry operations must determine rescue versus recovery from the victim's survivability profile, including location, condition, and elapsed time since the accident.", "cite": "MP 204.08, Phase II — Pre-entry Operations"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "Per MP 204.08, atmospheric monitoring during a confined space rescue must be done continuously, with readings communicated to Rescue Sector at least how often?", "opts": ["Every 15 minutes", "Every 10 minutes", "Every 30 minutes", "Every 5 minutes"], "answer": 3, "why": "Atmospheric monitoring is continuous and readings must be communicated to Rescue Sector at least every 5 minutes, by personnel with thorough knowledge of monitoring, assigned to a HazMat unit.", "cite": "MP 204.08, Phase II — Make the Rescue Area Safe"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "Which statement about breathing apparatus at a confined space entry is correct per MP 204.08?", "opts": ["SCBA is preferred over SABA for confined space entry", "SABA is the apparatus of choice; if SCBA must be used, crews maintain line of sight and exit before low-air alarm activation under the 75%-25% rule", "Entry personnel may remove their breathing apparatus and give it to the victim", "Pure oxygen may be given to a victim in a flammable atmosphere"], "answer": 1, "why": "SABA is the breathing apparatus of choice. If SCBA must be used, personnel maintain line of sight and exit prior to low-air alarm activation, following the 75%-25% rule.", "cite": "MP 204.08, Phase II — Make the Rescue Area Safe"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "Per MP 204.08, what minimum mechanical advantage must the retrieval system have?", "opts": ["4:1", "3:1", "2:1", "1:1"], "answer": 2, "why": "The retrieval system, with a back-up system readied and in place, must have a minimum of a 2:1 mechanical advantage.", "cite": "MP 204.08, Phase II — Make the Rescue Area Safe"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "A victim is found inside a confined space with a potentially flammable atmosphere. What does MP 204.08 prohibit?", "opts": ["Giving the victim pure oxygen and giving the victim your breathing apparatus", "Packaging the victim on a backboard before a secondary survey", "Treating serious injuries before removal", "Using a tag-line for communication"], "answer": 0, "why": "Rescuers must not administer pure oxygen to a victim in a potentially flammable atmosphere, and must not remove their breathing apparatus and give it to the victim.", "cite": "MP 204.08, Phase III — Victim Removal"}, {"mp": "204.08", "topic": "Confined Space Rescue", "q": "Immediately upon egress from a confined space, what must happen to the victim?", "opts": ["The victim is transported before any examination", "The victim is decontaminated only if visibly soiled", "The victim is interviewed by Command before treatment", "The victim is transferred to treatment personnel for ALS level examination"], "answer": 3, "why": "Phase III requires the victim to be transferred to treatment personnel for ALS level examination immediately upon egress from the confined space.", "cite": "MP 204.08, Phase III — Treatment"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "Which OSHA standard is the basis for emergency trench rescue operations under MP 204.09?", "opts": ["29 CFR 1910.146", "29 CFR 1926 Subpart P", "29 CFR 1910.120", "29 CFR 1926 Subpart M"], "answer": 1, "why": "MP 204.09 states OSHA Standard 29 CFR 1926 Subpart P regulates excavations and is the basis for emergency trench rescue operations.", "cite": "MP 204.09, Tactical Considerations"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "For emergency response under MP 204.09, an excavation is defined as any depression, hole, trench, or earth wall, man-made or natural, of what depth or greater?", "opts": ["2 feet", "3 feet", "4 feet", "6 feet"], "answer": 2, "why": "The MP defines an excavation as any depression, hole, trench, or earth wall, man-made or natural, of four feet or greater.", "cite": "MP 204.09, Tactical Considerations"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "What is Phoenix Fire Department policy on personnel entering an unsafe trench or excavation?", "opts": ["No personnel shall be allowed into an unsafe trench or excavation", "Entry is allowed with a Safety Officer present", "Entry is allowed for a viable victim only", "Entry is allowed once shoring is ordered"], "answer": 0, "why": "The stated policy is that no personnel shall be allowed into an unsafe trench or excavation.", "cite": "MP 204.09, Purpose"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "At a trench collapse, how far must apparatus remain from the failure, and where is Level 1 staging?", "opts": ["Apparatus 25 ft, staging 100 ft", "Apparatus 100 ft, staging 200 ft", "Apparatus 150 ft, staging 300 ft", "Apparatus 50 ft, Level 1 staging at least 150 ft"], "answer": 3, "why": "Phase I requires apparatus to remain at least 50 feet from the trench failure, and Command announces Level 1 staging at least 150 feet from the failure.", "cite": "MP 204.09, Phase I — Arrival"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "In pre-entry operations at a trench collapse, what perimeter is established and how far are civilians moved?", "opts": ["25-ft hazard zone, civilians 100 ft", "50-ft hazard zone, civilians at least 150 ft", "100-ft hazard zone, civilians 200 ft", "150-ft hazard zone, civilians 300 ft"], "answer": 1, "why": "A hazard zone perimeter of 50 feet is established around the collapse area, and non-essential civilians are removed at least 150 feet away.", "cite": "MP 204.09, Phase II — Make the General Area Safe"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "Per MP 204.09, how is traffic controlled at a trench collapse?", "opts": ["Reroute traffic 150 ft and shut down heavy equipment within 150 ft", "Shut down the roadway only; traffic may pass at 50 ft", "Reroute all non-essential traffic at least 300 ft away and shut down heavy equipment within 300 ft", "Reroute traffic 500 ft and shut down heavy equipment within 500 ft"], "answer": 2, "why": "Traffic control requires shutting down the roadway, staging apparatus at least 150 feet away, re-routing non-essential traffic at least 300 feet away, and shutting down heavy equipment within 300 feet of the collapse.", "cite": "MP 204.09, Phase II — Make the General Area Safe"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "What factors determine whether a trench incident is a rescue or a recovery operation?", "opts": ["By the survivability profile: victim location and condition, and elapsed time since the accident", "By the depth of the trench and the soil type", "By the number of TRT units on scene", "By whether shoring is already in place"], "answer": 0, "why": "Pre-entry operations must determine rescue versus recovery from the victim's survivability profile, including location, condition, and elapsed time since the accident.", "cite": "MP 204.09, Phase II — Pre-entry Operations"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "When making the rescue area safe at a trench, how should crews approach and what goes around the lip?", "opts": ["Approach from the collapsed side; place ladders around the lip", "Approach from the spoil pile side; place shoring around the lip", "Approach from any side; place tarps around the lip", "Approach from the ends if possible; place ground pads around the lip of the trench"], "answer": 3, "why": "Crews should approach the trench from the ends if possible and place ground pads around the lip of the trench.", "cite": "MP 204.09, Phase II — Make the Rescue Area Safe"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "Per MP 204.09, how many ingress and egress ladders go into the trench and how far apart at most?", "opts": ["1 ladder, centered", "At least 2 ladders, no more than 50 feet apart", "At least 3 ladders, no more than 25 feet apart", "2 ladders, no more than 100 feet apart"], "answer": 1, "why": "At least 2 ladders must be placed into the trench, no more than 50 feet apart.", "cite": "MP 204.09, Phase III — Make the Trench Safe"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "In a trench collapse, once a safe zone is created around the victim, how is the victim uncovered?", "opts": ["With heavy equipment to below the waist", "Completely, using large shovels from outside the trench", "To below the diaphragm using small shovels, buckets, or by hand", "To the chest using a backhoe"], "answer": 2, "why": "The victim is uncovered to below the diaphragm using small shovels, buckets, or by hand, and then assessed before being completely uncovered and packaged.", "cite": "MP 204.09, Phase III — Victim Removal / Incidents With Collapse"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "What treatment steps does MP 204.09 call for when the victim is reached in a trench?", "opts": ["Primary survey upon reaching the victim and C-spine precautions as soon as possible", "Package first, survey later", "Secondary survey only; primary survey after removal", "ALS treatment only after the trench is fully shored"], "answer": 0, "why": "Treatment calls for a primary survey upon reaching the victim, C-spine precautions as soon as possible, then a secondary survey correcting life threats.", "cite": "MP 204.09, Phase III — Treatment"}, {"mp": "204.09", "topic": "Trench Rescue Operations", "q": "At termination of a trench rescue, in what order is the shoring system removed?", "opts": ["First-in / first-out", "Heaviest first", "All at once by crane", "Last-in / first-out"], "answer": 3, "why": "Termination requires removing tools, equipment, and the trench shoring system last-in / first-out.", "cite": "MP 204.09, Phase IV — Termination"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "Per MP 204.10, what angle of inclination separates non-technical from technical rope rescue?", "opts": ["30 degrees", "50 degrees", "40 degrees", "60 degrees"], "answer": 2, "why": "Non-technical rescues are angles less than 40 degrees; technical rescues are from 40 to 90 degrees and require TRT-trained rescuers.", "cite": "MP 204.10, Tactical Considerations"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "Which NFPA standards must rope rescue techniques and equipment meet the intent of under MP 204.10?", "opts": ["NFPA 1670, 1006, and 1983", "NFPA 1500, 1582, and 1851", "NFPA 70E, 101, and 5000", "NFPA 472, 1001, and 1021"], "answer": 0, "why": "All rope rescue techniques and equipment must meet the intent of NFPA 1670 (operations and training), NFPA 1006 (technical rescuer qualifications), and NFPA 1983 (life safety rope and equipment).", "cite": "MP 204.10, Tactical Considerations"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "At a mountain rescue, what does the first arriving company officer do?", "opts": ["Remain at the base and establish Command only", "Assume Command, size up, and ascend the mountain with medical equipment to treat victims", "Wait for TRT before ascending", "Establish the Base LZ first"], "answer": 1, "why": "The first arriving company officer assumes Command, begins an immediate size-up, and ascends the mountain with medical equipment to treat victims in need of care.", "cite": "MP 204.10, Phase I — Arrival"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "If no witness is available at a mountain rescue, what should Command consider to locate the victim?", "opts": ["Sending a drone immediately", "Waiting for the victim to call out", "Searching the base area first", "Calling for a police helicopter (Firebird)"], "answer": 3, "why": "If no witness or other source of information is available, Command should consider calling for a police helicopter (Firebird) to locate the victim on the mountain.", "cite": "MP 204.10, Phase I — Size-Up"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "What factors determine whether a mountain incident is a rescue or a recovery operation?", "opts": ["By the survivability profile: victim location and condition, and elapsed time since the accident", "By the height of the mountain and the weather", "By the number of hikers on the trail", "By whether a helicopter is available"], "answer": 0, "why": "Pre-rescue operations must determine rescue versus recovery from the victim's survivability profile, including location, condition, and elapsed time since the accident.", "cite": "MP 204.10, Phase II — Pre-rescue Operations"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "In pre-rescue operations at a mountain incident, what must be done to make the area safe?", "opts": ["Close the mountain to all traffic including rescuers", "Evacuate the entire mountain range", "Secure the area, remove non-essential civilians, and control foot traffic on the trail", "Post a PIO at the trailhead only"], "answer": 2, "why": "Phase II requires securing the area, removing non-essential civilians, and controlling foot traffic on the trail, and making rescuers aware of hazards that cannot be secured.", "cite": "MP 204.10, Phase II — Make the Rescue Area Safe"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "How must the rescue plan be developed under MP 204.10?", "opts": ["Use the highest-risk option first to save time", "Consider the least amount of risk necessary; low-risk first; high-risk decided with Rescue Sector, Safety, Command, and the Technical Advisor; back-up plan in place before operations", "Follow the first plan proposed by any TRT member", "Decide the plan after entry"], "answer": 1, "why": "The plan must use the least risk necessary to effect the rescue, consider low-risk operations first, decide high-risk operations through consultation, and have a back-up plan in place before operations begin.", "cite": "MP 204.10, Phase III — Rope Rescue Operations"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "Which factors does MP 204.10 list to consider in using a rescue helicopter?", "opts": ["Fuel cost, pilot seniority, and media coverage", "Victim's insurance status and trail popularity", "Weather only", "Patient condition, difficult access, difficult terrain, time of day, environmental effects on rescuers"], "answer": 3, "why": "Helicopter use factors are the patient's condition, difficult access, difficult terrain, time of day, and environmental effects on rescuers.", "cite": "MP 204.10, Phase III — Helicopter Operations"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "Before considering helicopter use at a mountain rescue, Command must first determine if a rescue-qualified pilot is available. If so, who has the final say on if and how the helicopter is used?", "opts": ["Command", "The Rescue Sector officer", "The Pilot In Command (PIC)", "The Safety Officer"], "answer": 2, "why": "Once a rescue-qualified pilot is confirmed available, the Pilot In Command has the final say on if and how the helicopter is used.", "cite": "MP 204.10, Phase III — Helicopter Operations"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "Per MP 204.10, who establishes the Base LZ and the Mountain LZ?", "opts": ["Base LZ assigned to a TRT response unit; Mountain LZ assigned to TRT personnel on the mountain", "Base LZ by any first responder; Mountain LZ by the Safety Officer", "Both LZs by the police helicopter crew", "Base LZ by Command; Mountain LZ by the victim's party"], "answer": 0, "why": "Rescue Sector assigns the Base LZ function to a TRT response unit and the Mountain LZ function to TRT personnel on the mountain, calling for additional resources if needed.", "cite": "MP 204.10, Phase III — Helicopter Operations"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "What treatment sequence does MP 204.10 call for once the victim is reached?", "opts": ["Secondary survey first, then primary", "Primary survey, C-spine precautions as soon as possible, secondary survey correcting life threats, ALS treatment and transport", "Package and transport with no on-scene survey", "C-spine only after the victim is off the mountain"], "answer": 1, "why": "Treatment is a primary survey on reaching the victim, C-spine precautions as soon as possible, a secondary survey correcting life threats, and ALS treatment and transport when indicated.", "cite": "MP 204.10, Phase III — Treatment"}, {"mp": "204.10", "topic": "Mountain Rescue Operations", "q": "At termination of a mountain rescue, what does MP 204.10 require?", "opts": ["Leave equipment on the mountain for the next crew", "Return to service from the summit", "Critique before descending", "Ensure personnel accountability and descend the mountain with personnel and equipment"], "answer": 3, "why": "Termination requires ensuring personnel accountability and descending the mountain with personnel and equipment before returning to service.", "cite": "MP 204.10, Phase IV — Termination"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "Under MP 204.11, who may be designated Safety Officer at a water rescue?", "opts": ["Only the Battalion Chief", "Car 957 South or North, a Special Operations qualified Battalion Chief and/or FIT, or any experienced TRT Company Officer on the incident", "Only a HazMat Technician", "The first arriving company officer only"], "answer": 1, "why": "Safety Officer considerations for water rescue include Car 957 South or North, a Special Operations qualified Battalion Chief and/or FIT, and any experienced TRT Company Officer on the incident.", "cite": "MP 204.11, Phase I — Establish Command"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "During size-up at a water rescue, what should Command secure first to learn what happened and where the victim is?", "opts": ["A witness", "A drone for aerial reconnaissance", "The SRP gate schedule", "A boat"], "answer": 0, "why": "Size-up starts by securing a witness to determine exactly what happened and the location of any victims; with no witness, Command looks for clues on scene.", "cite": "MP 204.11, Phase I — Size-Up"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "What factors determine whether a water incident is a rescue or a recovery operation?", "opts": ["By the depth of the water and the current speed", "By the number of TRT units on scene", "By the survivability profile: victim location and condition, and elapsed time since the accident", "By whether a boat is available"], "answer": 2, "why": "Pre-rescue operations must determine rescue versus recovery from the victim's survivability profile, including location, condition, and elapsed time since the accident.", "cite": "MP 204.11, Phase II — Pre-rescue Operations"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "At a water rescue, how far must non-essential civilians be removed from the hazard zone?", "opts": ["50 feet", "100 feet", "200 feet", "At least 150 feet"], "answer": 3, "why": "Non-essential civilian personnel must be removed at least 150 feet away from the hazard zone.", "cite": "MP 204.11, Phase II — Make the General Area Safe"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "What minimum PPE must all personnel operating at or near the water wear under MP 204.11?", "opts": ["Turnouts and SCBA", "Personal flotation device (PFD), approved water rescue helmet, and approved footwear", "A wetsuit and fins", "A harness and tag-line only"], "answer": 1, "why": "Minimum PPE at or near the water is a personal flotation device, an approved water rescue helmet, and approved footwear.", "cite": "MP 204.11, Phase II — Make the Rescue Area Safe"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "Which hazards does MP 204.11 list to identify at a water rescue?", "opts": ["Water volume, velocity, debris, hydraulics, and depth (rising/falling)", "Water temperature only", "Current speed and wind direction only", "Debris and depth only"], "answer": 0, "why": "Hazards to identify include the volume of water, velocity, debris, hydraulics, and depth of the water, whether rising or falling.", "cite": "MP 204.11, Phase II — Make the Rescue Area Safe"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "Why does MP 204.11 assign personnel upstream and downstream at a water rescue?", "opts": ["Upstream to photograph the scene; downstream to direct traffic", "Upstream to block the river; downstream to launch boats", "Upstream to advise Rescue Sector of upstream hazards; downstream with throw bags to capture personnel or victims washed downstream", "Upstream to set anchors; downstream to treat victims"], "answer": 2, "why": "Upstream personnel advise Rescue Sector of hazards coming down, while downstream personnel with throw bags capture rescuers or victims washed downstream.", "cite": "MP 204.11, Phase II — Make the Rescue Area Safe"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "Per MP 204.11, what is the correct order of rescue from lowest to highest risk?", "opts": ["GO-ROW-HELO-WADE-THROW-REACH-TALK", "TALK-THROW-REACH-WADE-ROW-HELO-GO", "REACH-TALK-WADE-THROW-GO-ROW-HELO", "TALK-REACH-THROW-WADE-HELO-ROW-GO"], "answer": 3, "why": "The rescue plan order from low-risk to high-risk is TALK, REACH, THROW, WADE, HELO, ROW, GO, in that exact sequence.", "cite": "MP 204.11, Phase III — The Rescue Plan"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "During the WADE step of a water rescue, how far into the water may the team go, and how do they face?", "opts": ["Waist deep, facing downstream", "No further than knee deep, facing upstream", "Chest deep, facing the bank", "Ankle deep, facing downstream"], "answer": 1, "why": "The team enters facing upstream and no further than knee deep, taking a PFD and helmet for each victim, and assists the victims to shore.", "cite": "MP 204.11, Phase III — The Rescue Plan"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "During the GO step, which two actions does MP 204.11 prohibit?", "opts": ["Attaching to a lifeline without an approved quick-release mechanism, and doing a breath-hold surface dive to locate a victim", "Wearing a PFD and using a throw bag", "Briefing the team and using TRT personnel only", "Entering the water as a team"], "answer": 0, "why": "Rescue personnel must never be attached to a lifeline without an approved quick-release mechanism for water rescue, and must never do a breath-hold surface dive to locate a victim beneath the surface.", "cite": "MP 204.11, Phase III — The Rescue Plan"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "For helicopter use at a water rescue, who has the final say on if and how the helicopter is used?", "opts": ["Command", "The Technical Advisor", "The Pilot In Command (PIC), once a rescue-qualified pilot is confirmed available", "Rescue Sector"], "answer": 2, "why": "Command must first determine if a rescue-qualified pilot is available; if so, the Pilot In Command has the final say on if and how the helicopter is used.", "cite": "MP 204.11, Phase III — The Rescue Plan"}, {"mp": "204.11", "topic": "Water Rescue Operations", "q": "For a water incident in a Salt River Project canal or lateral, what does MP 204.11 direct crews to do?", "opts": ["Shut the canal gates themselves immediately", "Call 911 for SRP dispatch", "Wait for SRP to arrive before acting", "Call SRP's 24-hour emergency Association Dispatch Center (ADC) at 602-236-5296 and provide the closest cross streets"], "answer": 3, "why": "Crews call the SRP 24-hour emergency ADC at 602-236-5296 with the closest cross streets; SRP can provide gate control and other useful information.", "cite": "MP 204.11, Additional Considerations"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "What does MP 204.12 say about Phoenix Fire Department and AZ-TF1?", "opts": ["Phoenix sponsors AZ-TF1, one of 28 FEMA Urban Search & Rescue task forces in the nation", "Phoenix borrows AZ-TF1 from another state", "AZ-TF1 is a county team with no FEMA role", "AZ-TF1 handles only trench rescues"], "answer": 0, "why": "Phoenix Fire Department is the sponsoring agency of AZ-TF1, one of 28 FEMA Urban Search and Rescue task forces, and should be considered for structural collapse incidents.", "cite": "MP 204.12, Phase II — Pre-rescue Operations"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "During size-up at a structural collapse, where must apparatus be spotted?", "opts": ["As close to the collapse as possible", "At the nearest hydrant", "Inside the hazard zone for quick access", "Outside any potential secondary collapse zone"], "answer": 3, "why": "Size-up requires spotting apparatus outside any potential secondary collapse zone.", "cite": "MP 204.12, Phase I — Size-Up"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "Which hazards does MP 204.12 list for structural collapse size-up?", "opts": ["Smoke and heat only", "Secondary collapse, explosion and fire, broken gas and water lines, energized electrical lines, falling debris", "Dust and noise only", "Flooding and lightning only"], "answer": 1, "why": "Collapse hazards listed are secondary collapse, explosion and fire, broken gas and water lines, energized electrical lines, and falling debris.", "cite": "MP 204.12, Phase I — Size-Up"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "At a structural collapse, what should Command consider for staging and equipment?", "opts": ["Level 1 staging only", "No staging; all units to the scene", "Establishing Level 2 staging and calling for heavy machinery such as cranes and front-end loaders", "Level 3 staging at the nearest station"], "answer": 2, "why": "Command should consider establishing Level 2 staging and calling for heavy machinery and equipment such as cranes and front-end loaders.", "cite": "MP 204.12, Phase I — Size-Up"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "How far must non-essential civilians be removed from the collapse hazard zone perimeter?", "opts": ["At least 150 feet", "50 feet", "100 feet", "300 feet"], "answer": 0, "why": "Non-essential civilian personnel must be removed at least 150 feet away from the hazard zone perimeter.", "cite": "MP 204.12, Phase II — Make the General Area Safe"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "What is the makeup of the Building Triage team under MP 204.12?", "opts": ["Two TRT members and a PIO", "A Battalion Chief and two firefighters", "A search canine team only", "A TRT member trained in structural collapse shoring, a structural engineer, and a Hazardous Materials Technician"], "answer": 3, "why": "The Building Triage team consists of a TRT member trained in structural collapse shoring techniques, a structural engineer, and a HazMat Technician, and it assesses structural integrity and hazards using a building marking system.", "cite": "MP 204.12, Phase II — Make the Rescue Area Safe"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "What does a Search team consist of under MP 204.12?", "opts": ["Any available firefighters", "TRT personnel trained in specialized search equipment, plus search canines with handlers if available", "Structural engineers only", "Police officers and firefighters"], "answer": 1, "why": "A Search team consists of TRT personnel trained in the use of specialized search equipment, and search canines with their handlers if available.", "cite": "MP 204.12, Phase II — Make the Rescue Area Safe"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "What sequence does MP 204.12 require before TRT entry into a collapse area?", "opts": ["TRT enters immediately while first responders treat victims", "Obtain a PAR first, then remove surface victims", "First responders remove surface victims and the walking wounded, then all personnel are removed and a PAR is obtained before TRT operations begin", "Search teams enter first, then surface victims are removed"], "answer": 2, "why": "First responders remove surface victims and the walking wounded; then all rescue personnel are removed from the collapse area and a PAR is obtained before TRT operations begin under Rescue Sector.", "cite": "MP 204.12, Phase III — The Rescue"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "When may Search teams enter a building determined to be structurally unsafe?", "opts": ["Only after appropriate shoring and stabilization measures have been taken", "Immediately, with a Safety Officer present", "Only with a structural engineer inside", "Never under any circumstances"], "answer": 0, "why": "Search teams must not enter buildings determined to be structurally unsafe until appropriate shoring and stabilization measures have been taken.", "cite": "MP 204.12, Phase III — The Rescue"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "During selected debris removal at a collapse, what must crews do periodically?", "opts": ["Rotate crews every 10 minutes", "Re-mark the building each hour", "Shut down all heavy equipment", "Stop periodically to conduct search operations for additional victims"], "answer": 3, "why": "Selected debris removal must be stopped periodically to conduct search operations for additional victims, with special care to avoid a secondary collapse.", "cite": "MP 204.12, Phase III — The Rescue"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "What treatment sequence does MP 204.12 call for once a victim is reached?", "opts": ["Secondary survey first, then primary", "Primary survey, C-spine precautions as soon as possible, secondary survey correcting life threats, ALS treatment and transport", "Package and transport with no on-scene survey", "C-spine only after the victim is out of the collapse area"], "answer": 1, "why": "Treatment is a primary survey on reaching the victim, C-spine precautions as soon as possible, a secondary survey correcting life threats, and ALS treatment and transport when indicated.", "cite": "MP 204.12, Phase III — Treatment"}, {"mp": "204.12", "topic": "Structural Collapse Rescue Operations", "q": "If a collapse creates a confined space situation and the atmosphere cannot be made safe, what does MP 204.12 require before entry to retrieve a viable victim?", "opts": ["Enter with SCBA only", "Wait for OSHA before any entry", "Follow M.P. 204.08 Confined Space Rescue Operations", "Enter without respiratory protection to save time"], "answer": 2, "why": "The atmosphere must first be monitored by a qualified HazMat Technician; if it is unsafe it must be made safe, and if it cannot be changed and entry must be made for a viable victim, personnel follow MP 204.08.", "cite": "MP 204.12, Additional Considerations"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "At a tree rescue, what hazard zone is established and how far are civilians moved?", "opts": ["25-ft zone, civilians 100 ft", "100-ft zone, civilians 200 ft", "50-ft zone around the tree, civilians at least 150 ft away", "150-ft zone, civilians 300 ft"], "answer": 2, "why": "A hazard zone perimeter of 50 feet is established around the tree, and non-essential civilians are removed at least 150 feet away.", "cite": "MP 204.13, Phase II — Make the General Area Safe"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "Per MP 204.13, what is the order of rescue from lowest to highest risk?", "opts": ["Climb, ground ladders, aerial platform, self-rescue", "Self-rescue, aerial platform ladder truck, ground ladders, climb the tree", "Ground ladders, self-rescue, climb, aerial platform", "Aerial platform, climb, ground ladders, self-rescue"], "answer": 1, "why": "The rescue plan order from low-risk to high-risk is self-rescue, aerial platform ladder truck, ground ladders, then climbing the tree.", "cite": "MP 204.13, Phase III — The Rescue Plan"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "How is self-rescue accomplished under MP 204.13?", "opts": ["Place a ground ladder or aerial platform ladder under the victim and coach the victim to climb down", "Lower a rope and pull the victim down", "Have the victim jump to a safety net", "Climb up and carry the victim down"], "answer": 0, "why": "For self-rescue, a ground ladder or aerial platform ladder is placed under the victim and the victim is coached to climb down.", "cite": "MP 204.13, Phase III — The Rescue Plan"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "When considering an aerial platform ladder truck at a tree rescue, what hazards must crews consider?", "opts": ["Wind speed only", "The tree species only", "Traffic on the street only", "Power lines hidden in the tree, the angle of the ladder, and the distance the ladder must extend"], "answer": 3, "why": "Crews must consider hazards such as power lines hidden in the tree, the angle of the ladder, and the distance an aerial platform ladder needs to extend to reach the victim.", "cite": "MP 204.13, Phase III — The Rescue Plan"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "If ground ladders must be used at a tree rescue, where do the two ladders go?", "opts": ["Both ladders under the victim", "First ladder under the victim; second ladder alongside and slightly above the victim; both secured to the tree", "First ladder alongside the victim; second on the opposite side", "Both ladders on the same side, unsecured"], "answer": 1, "why": "The first ladder goes under the victim and the second goes alongside and slightly above the victim, and both ladders should be secured to the tree with webbing or a small piece of rope.", "cite": "MP 204.13, Phase III — The Rescue Plan"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "Who may climb the tree at a tree rescue, and how many rescuers are assigned?", "opts": ["Only trained TRT members; Rescue Sector assigns two rescuers", "Any firefighter; one rescuer", "Any two firefighters; no TRT requirement", "The Safety Officer alone"], "answer": 0, "why": "Tree climbing with approved equipment is only performed by trained TRT members, and Rescue Sector assigns two rescuers to climb and effect the rescue.", "cite": "MP 204.13, Phase III — The Rescue Plan"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "When rescuing the victim from a tree, what do the two climbing rescuers do?", "opts": ["Both climb to the victim and cut the tree down", "One climbs with a ladder while the other waits on the ground", "One climbs above and to the side to establish a lowering attachment; the other climbs to the victim and captures the victim onto an approved rescue harness, while a ground anchor and lowering system are established", "Both rescuers lower the victim by hand without a system"], "answer": 2, "why": "One rescuer climbs above and to the side to establish a lowering attachment while the other captures the victim onto an approved harness; on the ground an anchor and lowering system are established, the victim is disentangled, and then lowered.", "cite": "MP 204.13, Phase III — Rescue the Victim"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "When rescuers reach a victim in a tree, what must they determine in addition to completing a primary survey?", "opts": ["The victim's name and address", "The height of the tree", "The tree species", "The exact method of entrapment"], "answer": 3, "why": "On reaching the victim, rescuers complete a primary survey and determine the exact method of entrapment; a conscious victim who can assist is assessed for that, while an unconscious victim means the rescue must be completed quickly.", "cite": "MP 204.13, Phase III — Assess the Victim"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "What treatment does MP 204.13 call for after a tree rescue victim is lowered?", "opts": ["Primary survey only", "Complete a secondary survey; provide ALS treatment and transport to a hospital as indicated", "Transport with no survey", "Treat on the ground only if conscious"], "answer": 1, "why": "Treatment is a secondary survey on the victim, with ALS level treatment and transportation to a hospital as indicated.", "cite": "MP 204.13, Phase III — Treatment"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "At a tree rescue, what does the first arriving company officer do?", "opts": ["Assume Command and begin an immediate size-up", "Wait for TRT before assuming Command", "Establish the hazard zone before assuming Command", "Assign Rescue Sector before sizing up"], "answer": 0, "why": "The first arriving company officer assumes Command and begins an immediate size-up of the situation.", "cite": "MP 204.13, Phase I — Arrival"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "While making the rescue area safe at a tree rescue, what must crews watch for?", "opts": ["Only the victim's position", "Only the ladder angle", "All electrical lines in the vicinity, and falling debris, branches, or tree skirt — especially in wind", "Only traffic"], "answer": 2, "why": "Crews must maintain awareness of all electrical lines in the vicinity and watch for falling debris, branches, or tree skirt, which can become particularly problematic in windy conditions.", "cite": "MP 204.13, Phase II — Make the Rescue Area Safe"}, {"mp": "204.13", "topic": "Tree Rescue Operations", "q": "At termination of a tree rescue, what does MP 204.13 require?", "opts": ["Leave tools in the tree for the next crew", "Return to service before recovering equipment", "Critique on scene before accountability", "Ensure personnel accountability and recover all tools and equipment used"], "answer": 3, "why": "Termination requires ensuring personnel accountability and recovering all tools and equipment used in the rescue or recovery.", "cite": "MP 204.13, Phase IV — Termination"}, {"answer": 1, "cite": "MP 204.08, Phase II — Initiate Fire Department Confined Space Rescue Permit", "mp": "204.08", "opts": ["Only atmospheric hazards", "Atmospheric hazards, configuration hazard, engulfment hazard, or any other recognized hazard", "Only engulfment hazards", "Only hazards listed on the entry permit form"], "q": "Per MP 204.08, a Fire Department confined space rescue permit is required if the space has one or more of which hazards?", "topic": "Confined Space Rescue", "why": "A permit is required if the space has atmospheric hazards, a configuration hazard, an engulfment hazard, or any other recognized hazard."}, {"answer": 2, "cite": "MP 204.08, Phase II — Equipment", "mp": "204.08", "opts": ["Turnouts and SCBA only", "Helmet, gloves, and boots only", "Helmet, gloves, proper footwear, goggles, turnouts/Nomex or PBI jumpsuit, and a class III harness", "A wetsuit, helmet, and tag-line"], "q": "Per MP 204.08, what is the minimum PPE for confined space rescue entry?", "topic": "Confined Space Rescue", "why": "Minimum PPE is a helmet, gloves, proper footwear, goggles, turnouts or a Nomex/PBI jumpsuit, and a class III harness, with additional PPE as the hazard and atmospheric assessment indicate."}, {"answer": 0, "cite": "MP 204.08, Phase II — Ventilation", "mp": "204.08", "opts": ["When there is only one entry point", "When there are two or more entry points", "Only after the victim is removed", "Only when positive pressure fails twice"], "q": "Per MP 204.08, when should negative pressure ventilation be considered for a confined space?", "topic": "Confined Space Rescue", "why": "Positive and negative ventilation together in a push-pull configuration gives the greatest effect, and negative pressure ventilation should be considered if there is only one entry point."}, {"answer": 3, "cite": "MP 204.08, Phase II — Equipment", "mp": "204.08", "opts": ["A cell phone", "Shouting through the entry point", "Hand signals only", "A tag-line for communication or a message relay person"], "q": "If intrinsically safe communication equipment is not available at a confined space entry, what may entry personnel use instead?", "topic": "Confined Space Rescue", "why": "Intrinsically safe communication equipment shall be available; if not, entry personnel may use a tag-line or a message relay person."}, {"answer": 1, "cite": "MP 204.08, Phase I — Establish Command", "mp": "204.08", "opts": ["Directing TRT entry teams; filled after entry begins", "Ensuring the rescue plan developed by Rescue Sector and communicated to Command is sound for the safety and welfare of victims and rescuers; filled prior to implementing any rescue plan proposed by Rescue Sector", "Handling media briefings; filled at termination", "Monitoring the atmosphere; filled only if HazMat is delayed"], "q": "Per MP 204.08, what is the Technical Advisor responsible for, and when must the position be filled?", "topic": "Confined Space Rescue", "why": "The Technical Advisor ensures the rescue plan is sound in terms of the safety and welfare of both victims and rescuers, and the position should be filled before any rescue plan proposed by Rescue Sector is implemented."}, {"answer": 2, "cite": "MP 204.08, Phase III — Victim Removal", "mp": "204.08", "opts": ["The victim should always be carried ahead of the rescuer", "The victim should be left at the entry point while rescuers exit first", "Rescuers should not allow the victim between the rescuer and the point of egress, except when one rescuer must pull while another pushes", "The victim should be placed between two rescuers at all times"], "q": "Per MP 204.08, when removing a victim from a confined space, where should the victim be relative to the rescuer and the point of egress?", "topic": "Confined Space Rescue", "why": "Rescuers should not allow the victim between the rescuer and the point of egress, except where one rescuer must pull the victim while another pushes."}, {"answer": 0, "cite": "MP 204.09, Tactical Considerations", "mp": "204.09", "opts": ["Removing soil or debris, adding weight near the edge, vibration such as vehicle movement, rain, or simply the passage of time", "Only the use of hydraulic shoring", "Only the victim's movement", "Only high winds"], "q": "Per MP 204.09, which of the following may cause additional collapse at any time during a trench rescue?", "topic": "Trench Rescue Operations", "why": "Additional collapse is a primary hazard: removing soil or debris, adding weight near the edge, vibration, rain, or simply time passing may cause it at any point in the operation."}, {"answer": 3, "cite": "MP 204.09, Phase III — Make the Trench Safe", "mp": "204.09", "opts": ["Timber shore only", "Hydraulic shore only", "Pneumatic shore only", "Hydraulic shore, pneumatic shore, or timber shore"], "q": "Per MP 204.09, which shoring systems may be used to make a trench safe?", "topic": "Trench Rescue Operations", "why": "Rescue Sector decides on the shoring system to be used: hydraulic shore, pneumatic shore, or timber shore."}, {"answer": 1, "cite": "MP 204.09, Phase II — Make the Rescue Area Safe", "mp": "204.09", "opts": ["Only its height", "Its improper angle of repose and general raveling, and look for fissures or an unstable spoil pile", "Only its color", "Only whether it is wet"], "q": "When making the rescue area safe at a trench, what must crews assess about the spoil pile?", "topic": "Trench Rescue Operations", "why": "Crews must look for unidentified hazards such as fissures or an unstable spoil pile and assess the spoil pile for improper angle of repose and general raveling."}, {"answer": 2, "cite": "MP 204.09, Phase III — Make the Trench Safe", "mp": "204.09", "opts": ["In the collapsed zone, from one end only", "Outside the trench, from the apparatus", "In the non-collapsed area of the trench, from both ends if possible, using an approved shoring system", "In the spoil pile area, from the street"], "q": "Per MP 204.09, where is the safe zone created in a trench, and from where?", "topic": "Trench Rescue Operations", "why": "A safe zone is created in the non-collapsed area of the trench, from both ends if possible, by implementing an approved shoring system."}, {"answer": 0, "cite": "MP 204.09, Phase III — Victim Removal / Incidents Without Collapse", "mp": "204.09", "opts": ["Remove objects trapping the victim such as pipes, lumber, or machinery, assess the victim's condition, then properly package and remove the patient", "Begin heavy equipment excavation immediately", "Remove the victim before creating a safe zone", "Wait for a structural engineer before touching the victim"], "q": "At a trench incident without collapse, after creating a safe zone around the victim, what is done next?", "topic": "Trench Rescue Operations", "why": "Without collapse, crews create a safe zone around the victim, remove objects trapping the victim such as pipes, lumber, or machinery, assess the victim's condition, then package and remove the patient."}, {"answer": 3, "cite": "MP 204.09, Additional Considerations — Command Structure", "mp": "204.09", "opts": ["The first arriving engine company", "The Safety Officer", "The Technical Advisor", "Any ALS company assigned to the incident"], "q": "Per MP 204.09, to whom should Treatment Sector be assigned at a trench rescue?", "topic": "Trench Rescue Operations", "why": "Treatment Sector should be assigned to any ALS company assigned to the incident."}, {"answer": 1, "cite": "MP 204.10, Tactical Considerations", "mp": "204.10", "opts": ["Any rescue above 100 feet of elevation", "Any rescue attempt that requires rope and/or rope systems and related equipment to safely gain access to and remove patients from hazardous geographic areas with limited access", "Any rescue using a helicopter", "Any rescue on a slope steeper than 60 degrees"], "q": "Per MP 204.10, what defines a rope rescue?", "topic": "Mountain Rescue Operations", "why": "Rope rescue is any rescue attempt requiring rope and/or rope systems and related equipment to safely gain access to, and remove patients from, hazardous geographic areas or locations with limited access."}, {"answer": 2, "cite": "MP 204.10, Phase I — Establish Command", "mp": "204.10", "opts": ["NFPA 1006", "NFPA 1983", "NFPA 1670", "OSHA 29 CFR 1926 Subpart P"], "q": "Under MP 204.10, the Safety Officer at a mountain rescue is designated per which standard?", "topic": "Mountain Rescue Operations", "why": "MP 204.10 directs that a Safety Officer be designated per NFPA 1670, the standard on operations and training for technical search and rescue incidents."}, {"answer": 0, "cite": "MP 204.10, Additional Considerations — Other Considerations", "mp": "204.10", "opts": ["Be 'on-rope' and 'tied-in'", "Work without ropes to move faster", "Stay at least 50 feet from the edge at all times", "Clip in only when the victim is located"], "q": "Per MP 204.10, what must rescuers do when operating near an edge during a mountain rescue?", "topic": "Mountain Rescue Operations", "why": "Rescuers shall be 'on-rope' and 'tied-in' when operating near an edge."}, {"answer": 3, "cite": "MP 204.10, Additional Considerations — Other Considerations", "mp": "204.10", "opts": ["Carried in a rescuer's arms", "In a harness or litter so as not to fall out if inverted at any time during the rescue", "Tied to a rope by one ankle", "Placed on a backboard without straps"], "q": "Per MP 204.10, how should victims be secured during a mountain rescue?", "topic": "Mountain Rescue Operations", "why": "Victims should be secured in a harness or litter so as not to fall out if inverted at any time during the rescue operation."}, {"answer": 1, "cite": "MP 204.10, Additional Considerations — Command Structure", "mp": "204.10", "opts": ["The first TRT unit on the mountain", "The first non-TRT unit that ascends the mountain", "The helicopter crew only", "The Safety Officer"], "q": "Per MP 204.10, to whom can Treatment Sector be assigned at a mountain rescue?", "topic": "Mountain Rescue Operations", "why": "Treatment Sector can be assigned to the first non-TRT unit that ascends the mountain."}, {"answer": 2, "cite": "MP 204.10, Phase I — Size-Up", "mp": "204.10", "opts": ["The nearest hiker only", "The news media", "A witness or park ranger", "The landowner only"], "q": "During size-up at a mountain rescue, whom should Command secure to help determine the victim's location and condition?", "topic": "Mountain Rescue Operations", "why": "Size-up calls for securing a witness or park ranger to assist in gathering information to determine the location and condition of victims."}, {"answer": 0, "cite": "MP 204.11, Phase I — Establish Command", "mp": "204.11", "opts": ["Both Safety Officer and Technical Advisor", "Safety Officer only", "Technical Advisor only", "Rescue Sector only"], "q": "In MP 204.11, Car 957 South or North is listed as a consideration for which positions at a water rescue?", "topic": "Water Rescue Operations", "why": "Car 957 South or North appears in the considerations for both the Safety Officer and the Technical Advisor — a detail unique to the water rescue MP."}, {"answer": 3, "cite": "MP 204.11, Phase III — The Rescue Plan", "mp": "204.11", "opts": ["Only a throw bag", "Only a boat", "A ladder laid flat on the water", "An arm, pike pole, rescue hook, or any other such object"], "q": "In the REACH step of a water rescue, what may be extended to the victim?", "topic": "Water Rescue Operations", "why": "REACH means extending an arm, pike pole, rescue hook, or any other such object to reach the victim and pull them from the water."}, {"answer": 1, "cite": "MP 204.11, Phase III — The Rescue Plan", "mp": "204.11", "opts": ["A rope tied to the rescuer; the victim pulls the rescuer in", "A throw-bag rescue line or other approved safety flotation device, then the victim is 'pendulum-belayed' or 'hauled' to the bank", "A life ring with no line attached", "A boat anchor"], "q": "In the THROW step of a water rescue, what is thrown to the victim and how is the victim brought to the bank?", "topic": "Water Rescue Operations", "why": "THROW is an attempt to throw the victim a throw-bag rescue line or other approved safety flotation device and 'pendulum-belay' or 'haul' the victim to the bank."}, {"answer": 2, "cite": "MP 204.11, Phase III — The Rescue Plan", "mp": "204.11", "opts": ["A helicopter to the opposite bank", "A company on the same bank to launch a boat", "A company on the opposite bank to assist in establishing an anchor for an approved rope system", "A Safety Officer to each bank"], "q": "In the ROW step of a water rescue, what does Rescue Sector assign?", "topic": "Water Rescue Operations", "why": "If a boat-based operation is used, Rescue Sector assigns a company on the opposite bank to assist in establishing an anchor for an approved rope system."}, {"answer": 0, "cite": "MP 204.11, Phase III — Assess the Victim", "mp": "204.11", "opts": ["If the victim is conscious, determine if the victim can assist in the rescue; if unconscious, complete the rescue as quickly as possible", "Always wait for a boat before assessing the victim", "If the victim is conscious, leave the victim in place until TRT arrives", "If the victim is unconscious, begin a secondary survey in the water"], "q": "When rescuers reach the victim at a water rescue, what is done after the primary survey?", "topic": "Water Rescue Operations", "why": "On reaching the victim a primary survey is completed; if the victim is conscious, rescuers determine if the victim can assist, and if unconscious, the rescue must be completed as quickly as possible."}, {"answer": 3, "cite": "MP 204.11, Additional Considerations — Other Considerations", "mp": "204.11", "opts": ["Sunburn", "Water clarity", "Algae growth", "Hypothermia"], "q": "Per MP 204.11, which effect of water conditions must crews pay particular attention to?", "topic": "Water Rescue Operations", "why": "Crews must consider the effects of inclement weather and water conditions on the hazard profile, victims, and rescuers, with particular attention to the effects of hypothermia."}, {"answer": 1, "cite": "MP 204.12, Phase I — Arrival", "mp": "204.12", "opts": ["To keep the media away from the scene", "Because unorganized, volunteer rescue efforts by civilian personnel create an unsafe situation for the volunteers as well as rescuers", "To speed up debris removal", "Because TRT units cannot operate without it"], "q": "Per MP 204.12, why must Command take strong control early at a structural collapse?", "topic": "Structural Collapse Rescue Operations", "why": "A collapse is likely to have unorganized, volunteer rescue efforts by civilians, which creates an unsafe situation for the volunteers and rescuers, so Command must focus early on building a strong Command structure."}, {"answer": 2, "cite": "MP 204.12, Phase II — Make the Rescue Area Safe", "mp": "204.12", "opts": ["To triage victims", "To operate heavy machinery", "To control the flow and maintain personnel accountability of rescue personnel in the collapse area", "To mark buildings with the marking system"], "q": "At a structural collapse, what is the Lobby Sector's job?", "topic": "Structural Collapse Rescue Operations", "why": "Command establishes a Lobby Sector to control the flow and maintain personnel accountability of rescue personnel in the collapse area."}, {"answer": 0, "cite": "MP 204.12, Phase III — The Rescue", "mp": "204.12", "opts": ["Identifying, selecting, and prioritizing the buildings with the highest probability of finding and rescuing live victims, and using a building marking system to indicate structural conditions and hazards", "Removing all surface victims", "Operating the cranes and front-end loaders", "Providing ALS treatment at the rescue site"], "q": "What is the Building Triage team responsible for at a structural collapse?", "topic": "Structural Collapse Rescue Operations", "why": "The Building Triage team identifies, selects, and prioritizes buildings with the highest probability of success in finding and rescuing live victims, and uses a building marking system to indicate structural conditions and hazards to search and rescue personnel."}, {"answer": 3, "cite": "MP 204.12, Phase II — Make the Rescue Area Safe", "mp": "204.12", "opts": ["A helicopter landing zone at the scene", "That all roads within a mile are closed", "A fuel station near the scene", "A transportation corridor with roadways clear in and out of the collapse site, considering a liaison with the Police Department"], "q": "Per MP 204.12, what must Command ensure so apparatus and heavy equipment can reach the collapse site?", "topic": "Structural Collapse Rescue Operations", "why": "Command shall ensure roadways are clear in and out of the collapse site so apparatus and heavy equipment have access, and should consider a liaison with the Police Department to accomplish this."}, {"answer": 1, "cite": "MP 204.12, Phase III — The Rescue", "mp": "204.12", "opts": ["Dumped immediately without record", "Marked as to the general location found and the final location of the debris, to aid the investigative process", "Sorted by weight only", "Left in place until the coroner arrives"], "q": "During general debris removal at a structural collapse, how should each load of debris be handled?", "topic": "Structural Collapse Rescue Operations", "why": "Each load should be marked as to the general location found and final location of the debris to aid in the investigative process."}, {"answer": 2, "cite": "MP 204.12, Additional Considerations — Other Considerations", "mp": "204.12", "opts": ["Any firefighter with a four-gas meter borrowed from the engine", "The Safety Officer with a thermal camera", "A qualified Hazardous Materials Technician with an appropriate air monitoring device", "The Building Triage team with a search camera"], "q": "At a structural collapse that presents a confined space situation, who must monitor the atmosphere before entry, and with what?", "topic": "Structural Collapse Rescue Operations", "why": "Before entering any space, the atmosphere must be monitored by a qualified Hazardous Materials Technician with an appropriate air monitoring device to determine if the space is safe to enter."}, {"answer": 0, "cite": "MP 204.13, Phase III — The Rescue Plan", "mp": "204.13", "opts": ["When possible, consider removing obstacles that may be in the way of the aerial platform ladder truck", "Ignore obstacles; the platform can push through them", "Remove the tree's branches only after the rescue", "Never move obstacles; reposition the victim instead"], "q": "When positioning an aerial platform ladder truck at a tree rescue, what should crews consider doing about obstacles in its way?", "topic": "Tree Rescue Operations", "why": "Crews should consider hazards such as power lines hidden in the tree, the ladder angle, and the distance the ladder must extend, and when possible consider removing obstacles that may be in the way of the aerial platform ladder truck."}, {"answer": 3, "cite": "MP 204.13, Phase III — The Rescue Plan", "mp": "204.13", "opts": ["With duct tape", "They do not need to be secured", "With a chain and padlock", "With a piece of webbing or a small piece of rope"], "q": "Per MP 204.13, how should ground ladders be secured to the tree?", "topic": "Tree Rescue Operations", "why": "Both ladders should be secured to the tree, and a piece of webbing or small piece of rope works well for securing the ladder to the tree."}, {"answer": 1, "cite": "MP 204.13, Phase III — The Rescue Plan", "mp": "204.13", "opts": ["Cutting down the tree; low-risk", "Removing fronds or branches from the tree to reach the victim; tree climbing is a high-risk operation", "Using a chainsaw from the ground; medium-risk", "Climbing without equipment; standard-risk"], "q": "Per MP 204.13, what may be necessary to reach the victim when climbing a tree, and how is tree climbing classified?", "topic": "Tree Rescue Operations", "why": "It may be necessary to remove fronds or branches from the tree to reach the victim, and tree climbing is a high-risk operation."}, {"answer": 2, "cite": "MP 204.13, Phase III — Rescue the Victim", "mp": "204.13", "opts": ["By shaking the tree", "By waiting for the victim to free themselves", "By disentangling the victim, which may include cutting away any system the victim used to climb the tree, then lowering the victim to the ground", "By cutting down the entire tree"], "q": "Once the lowering system is attached to a tree rescue victim, how is the victim disentangled from the tree?", "topic": "Tree Rescue Operations", "why": "Once the lowering system is attached, the victim is disentangled from the tree, which may include cutting away any system the victim used to climb the tree, and then lowered to the ground."}, {"answer": 0, "cite": "MP 204.13, Phase IV — Termination", "mp": "204.13", "opts": ["Consider leaving everything in place until the investigative process has been completed", "Remove everything immediately regardless", "Leave only the ladders in place", "Donate the equipment to the responsible party"], "q": "At termination of a tree rescue in which there has been a fatality, what should be considered regarding tools and equipment?", "topic": "Tree Rescue Operations", "why": "In cases of a fatality, consider leaving everything in place until the investigative process has been completed."}, {"answer": 3, "cite": "MP 204.13, Tactical Considerations", "mp": "204.13", "opts": ["The Incident Action Profile", "The Technical Rescue Profile", "The Survivability Profile", "The Phoenix Fire Department Risk Management Profile"], "q": "Per MP 204.13, which profile must be applied to all tree rescue operations and continuously re-assessed throughout the incident?", "topic": "Tree Rescue Operations", "why": "The Phoenix Fire Department Risk Management Profile shall be applied to all tree rescue operations and shall be continuously re-assessed throughout the incident."}];
